def svg_heatmap(matrix_df, title='', width=760, height=420, value_fmt=lambda v:f'{v:.1f}'):
    mat=matrix_df.copy()
    rows=list(mat.index); cols=list(mat.columns)
    vals=[float(v) for v in mat.to_numpy().flatten() if not pd.isna(v)]
    minv=min(vals) if vals else 0; maxv=max(vals) if vals else 1
    margin_l,margin_t,margin_r,margin_b=190,70,30,40
    cell_w=(width-margin_l-margin_r)/max(len(cols),1); cell_h=(height-margin_t-margin_b)/max(len(rows),1)
    def col(v):
        if pd.isna(v): return '#1e293b'
        t=(float(v)-minv)/(maxv-minv) if maxv>minv else 0.5
        # interpolate slate -> cyan -> amber
        if t<0.5:
            a=t/0.5; c1=(30,41,59); c2=(14,165,233)
        else:
            a=(t-0.5)/0.5; c1=(14,165,233); c2=(245,158,11)
        rgb=tuple(int(c1[i]+(c2[i]-c1[i])*a) for i in range(3))
        return '#%02x%02x%02x'%rgb
    parts=[f'<svg viewBox="0 0 {width} {height}" role="img" aria-label="{esc(title)}" xmlns="http://www.w3.org/2000/svg"><rect width="{width}" height="{height}" rx="18" fill="#0f172a"/>']
    parts.append(f'<text x="24" y="30" fill="#e2e8f0" font-size="16" font-weight="700">{esc(title)}</text>')
    for j,c in enumerate(cols):
        parts.append(f'<text x="{margin_l+j*cell_w+cell_w/2:.1f}" y="58" text-anchor="middle" fill="#cbd5e1" font-size="12" font-weight="700">{esc(c)}</text>')
    for i,r in enumerate(rows):
        y=margin_t+i*cell_h
        parts.append(f'<text x="18" y="{y+cell_h*0.62:.1f}" fill="#cbd5e1" font-size="11">{esc(str(r)[:30])}</text>')
        for j,c in enumerate(cols):
            v=mat.loc[r,c]
            x=margin_l+j*cell_w
            parts.append(f'<rect x="{x+2:.1f}" y="{y+2:.1f}" width="{cell_w-4:.1f}" height="{cell_h-4:.1f}" rx="6" fill="{col(v)}"/>')
            parts.append(f'<text x="{x+cell_w/2:.1f}" y="{y+cell_h*0.62:.1f}" text-anchor="middle" fill="#f8fafc" font-size="11" font-weight="700">{esc(value_fmt(v)) if not pd.isna(v) else "—"}</text>')
    parts.append('</svg>')
    return ''.join(parts)

